escenas.animacion:
const W=A.W, acc=A.accent;
const T2020=A.k('2020,',0.333), TA=A.k('artista',1.0), TT=A.k('tráfico',1.667), TF=A.k('falso',2.0);
const TG=A.k('Google',2.667), TC=A.k('caminando',3.333), TK=A.k('carrito',4.333), TL=A.k('lleno',4.667);
const T99=A.k('99',5.333), TCel=A.k('celulares.',5.667);
A.bg('#0a0f1e','#1a0a12');

// ---- cuadrícula del mapa ----
const pMap=A.p(TA-0.1,0.9,'softLand');
if(pMap>0){
  const streets=[[[180,430],[180,1110]],[[540,430],[540,1110]],[[900,430],[900,1110]],[[40,560],[1040,560]],[[40,1070],[1040,1070]]];
  streets.forEach((s,i)=>A.line(s,{stroke:'#4a5878',lw:14,alpha:0.35,progress:A.clamp(pMap*1.4-i*0.1)}));
}
// ---- avenida principal ----
const pRoad=A.p(TA,0.6,'glide');
if(pRoad>0){
  A.rect(40,845,1000*pRoad,110,{r:55,fill:'#273047',alpha:0.95});
  const pRed=A.p(TT,0.7,'whip');
  if(pRed>0) A.rect(40,845,Math.max(110,1000*pRed),110,{r:55,fill:acc,glow:40,alpha:0.95});
  A.line([[90,900],[990*pRoad+40,900]],{stroke:'#ffffff',lw:5,alpha:0.35,dash:[30,26]});
  if(pRed>0){
    const la=1-A.p(TC,0.4,'accelExit');
    A.label('TRÁFICO',540,1020,{size:56,bg:acc,color:'#fff',scale:A.pop(TT+0.2),alpha:la});
  }
}

// ---- 2020 ----
if(t>=T2020){
  const pm=A.p(TA,0.6,'whip');
  const s=A.pop(T2020,0.45);
  const y=A.lerp(660,480,pm), size=A.lerp(300,90,pm);
  A.with(()=>{A.text('2020',540,y,{size,color:'#ffffff',weight:900,align:'center',alpha:A.lerp(1,0.75,pm)});},{x:540,y:y,scale:s});
}

// ---- persona y carrito ----
const pWalk=A.p(TC,A.dur-TC,'cruise');
const walking=t>TC;
const px=A.lerp(170,520,pWalk);
const bob=walking?Math.abs(Math.sin((t-TC)*9))*-8:0;
if(t>=TA){
  A.with(()=>{A.person(px,955+bob,{scale:1.3,color:'#ffffff'});},{x:px,y:955,scale:A.pop(TA,0.5)});
}
const cx=px+90, cw=240, cTop=820, cBot=935;
const pCart=A.pop(TC,0.45);
const cartBump=t>TK?A.lerp(1.15,1,A.p(TK,0.45,'bounceHard')):1;
if(t>=TC){
  // señales
  A.rings(cx+cw/2,700,TC+0.2,{count:3,speed:320,gap:0.55,maxR:220,color:acc,lw:4,alpha:0.5});
  A.with(()=>{
    // celulares
    const pc=A.p(TL,(T99+0.25)-TL,'glide');
    const n=Math.round(99*pc);
    for(let i=0;i<n;i++){
      const col=i%10,row=Math.floor(i/10);
      const off=(row%2)*6;
      const x=cx+12+col*22+off-3, y=cBot-12-(row+1)*28;
      ctx.fillStyle='#0e1322';ctx.fillRect(x,y,17,25);
      ctx.strokeStyle='#ffffff';ctx.lineWidth=2;ctx.strokeRect(x,y,17,25);
      ctx.fillStyle=i%7===0?acc:'#9fd3ff';ctx.globalAlpha=0.9;ctx.fillRect(x+3,y+3,11,17);ctx.globalAlpha=1;
    }
    // canasta de alambre
    A.lib.inkPath(ctx,[[cx,cTop],[cx+cw,cTop],[cx+cw-20,cBot],[cx+20,cBot]],{width:6,color:'#ffffff',closed:true});
    A.lib.hatch(ctx,[[cx,cTop],[cx+cw,cTop],[cx+cw-20,cBot],[cx+20,cBot]],{angle:0.8,spacing:22,width:2,color:'rgba(255,255,255,0.35)'});
    A.line([[cx,cTop],[cx-50,cTop-50]],{stroke:'#ffffff',lw:7});
    A.line([[cx-50,cTop-50],[px+20,cTop-40+bob]],{stroke:'#ffffff',lw:7});
    A.circle(cx+40,cBot+14,14,{fill:'#0a0f1e',stroke:'#ffffff',lw:5});
    A.circle(cx+cw-40,cBot+14,14,{fill:'#0a0f1e',stroke:'#ffffff',lw:5});
  },{x:cx+cw/2,y:cBot,scale:pCart*cartBump});
  if(t>=TK){
    const la=1-A.p(TL+0.2,0.4,'accelExit');
    A.label('CARRITO',cx+cw/2,1020,{size:52,bg:'#ffffff',color:'#0a0f1e',scale:A.pop(TK,0.4),alpha:la});
  }
}

// ---- pin de Google Maps ----
if(t>=TG){
  const pd=A.p(TG,0.55,'bounceHard');
  const pinX=880, pinY=A.lerp(430,860,pd);
  A.rings(pinX,870,TG+0.4,{count:2,speed:260,gap:0.35,maxR:150,color:acc,lw:5,alpha:0.7});
  ctx.save();ctx.fillStyle=acc;ctx.shadowColor=acc;ctx.shadowBlur=30;
  ctx.beginPath();ctx.moveTo(pinX,pinY);
  ctx.bezierCurveTo(pinX-30,pinY-45,pinX-55,pinY-70,pinX-55,pinY-105);
  ctx.arc(pinX,pinY-105,55,Math.PI,0);
  ctx.bezierCurveTo(pinX+55,pinY-70,pinX+30,pinY-45,pinX,pinY);
  ctx.fill();ctx.restore();
  A.lib.inkPath(ctx,[[pinX,pinY],[pinX-55,pinY-105],[pinX,pinY-160],[pinX+55,pinY-105]],{width:4,color:'#ffffff',closed:true,draw:1});
  A.circle(pinX,pinY-105,20,{fill:'#ffffff'});
}

// ---- sello FALSO ----
if(t>=TF){
  const pi=A.p(TF,0.35,'crashIn');
  const out=A.p(TC,0.4,'accelExit');
  const sc=A.lerp(2.4,1,pi)*A.lerp(1,0.6,out);
  const sh=(t>TF+0.3&&t<TF+0.6)?14:0;
  A.with(()=>{
    A.rect(300,570,480,170,{r:18,stroke:acc,lw:12,fill:'rgba(10,15,30,0.85)'});
    A.text('FALSO',540,700,{size:140,color:acc,weight:900,align:'center'});
  },{x:540,y:655,scale:sc,rot:-0.12,alpha:pi*(1-out),shake:sh});
  A.flash(TF+0.3,0.25,0.35);
}

// ---- contador 99 ----
if(t>=TL){
  const pc=A.p(TL,(T99+0.25)-TL,'glide');
  const hit=T99+0.25;
  const s=t>hit?A.pop(hit,0.4):1;
  const sh=(t>hit&&t<hit+0.3)?12:0;
  A.with(()=>{
    A.text(A.counter(0,99,pc,0),540,1600,{size:240,color:acc,weight:900,align:'center',stroke:'#ffffff',strokeWidth:t>hit?6:0});
  },{x:540,y:1520,scale:A.p(TL,0.4,'snapSettle')*s,shake:sh});
  if(t>hit){A.flash(hit,0.25,0.3);A.rings(540,1520,hit,{count:2,speed:500,gap:0.2,maxR:300,color:acc,lw:5,alpha:0.6});}
  if(t>=TCel) A.label('CELULARES',540,1700,{size:56,bg:'#ffffff',color:'#0a0f1e',scale:A.pop(TCel,0.4)});
}

A.bg('#0B1424', '#050A14', true);
const W = A.W, ACC = A.accent, RED = '#FF4D4D';
const kRev = A.k('revela', 0.667), kTru = A.k('truco:', 1.333), kG = A.k('Google', 1.667), kM = A.k('Maps', 2.0);
const kNo = A.k('no', 2.333), kAut = A.k('autos.', 3.333), kVe = A.k('Ve', 3.667), kTel = A.k('teléfonos.', 4.333);

// --- Calle ---
const roadIn = A.p(0, 0.7, 'softLand');
const roadTop = 700, roadBot = 980;
A.with(() => {
  A.rect(-20, roadTop, W + 40, roadBot - roadTop, { fill: '#1A2436', stroke: 'rgba(255,255,255,0.5)', lw: 4 });
  A.lib.hatch(ctx, [[-20, roadTop], [W + 20, roadTop], [W + 20, roadBot], [-20, roadBot]], { angle: 0.6, spacing: 26, width: 1, color: 'rgba(255,255,255,0.05)' });
  // línea central discontinua animada
  const off = (t * 220) % 120;
  for (let x = -120 + off; x < W + 120; x += 120) A.rect(x, (roadTop + roadBot) / 2 - 4, 60, 8, { fill: 'rgba(255,255,255,0.55)', r: 3 });
}, { alpha: roadIn, x: 540, y: 840, scale: A.lerp(1.08, 1, roadIn) });

// --- Haz de escaneo del pin ---
const pinP = A.p(kG, 0.55, 'snapSettle');
const beam = A.p(kM, 0.5, 'softLand');
const pinY = A.lerp(380, 520, pinP);
if (beam > 0) {
  ctx.save();
  const g = ctx.createLinearGradient(0, pinY, 0, roadBot);
  g.addColorStop(0, 'rgba(255,212,0,0.35)'); g.addColorStop(1, 'rgba(255,212,0,0.03)');
  ctx.fillStyle = g; ctx.globalAlpha = beam;
  const sw = A.lerp(20, 520, beam);
  ctx.beginPath(); ctx.moveTo(540, pinY + 40); ctx.lineTo(540 + sw, roadBot); ctx.lineTo(540 - sw, roadBot); ctx.closePath(); ctx.fill();
  // línea de escaneo que barre
  const sy = roadTop + ((t * 260) % (roadBot - roadTop));
  ctx.globalAlpha = beam * 0.7; ctx.fillStyle = ACC; ctx.fillRect(540 - sw * ((sy - pinY) / (roadBot - pinY)), sy, 2 * sw * ((sy - pinY) / (roadBot - pinY)), 3);
  ctx.restore();
}

// --- Autos y teléfonos ---
const fadeCars = A.p(kNo, 0.9, 'softInOut');
const phoneT = kVe;
const cars = [
  { b: 0, y: 760, v: 210, c: '#4FA3FF' }, { b: 420, y: 760, v: 210, c: '#E8EEF7' }, { b: 860, y: 760, v: 210, c: '#FF8A3D' },
  { b: 200, y: 890, v: 160, c: '#9B7BFF' }, { b: 680, y: 890, v: 160, c: '#4FD18B' }, { b: 1120, y: 890, v: 160, c: '#4FA3FF' }
];
const shake = (t > phoneT && t < phoneT + 0.3) ? 6 * (1 - (t - phoneT) / 0.3) : 0;
A.with(() => {
  cars.forEach((c, i) => {
    const x = ((c.b + c.v * t) % 1400) - 200;
    const a = roadIn * A.lerp(1, 0.25, fadeCars);
    // carrocería
    ctx.save();
    if (fadeCars > 0.5) ctx.setLineDash([12, 10]);
    A.rect(x - 85, c.y - 42, 170, 84, { r: 22, fill: fadeCars > 0 ? 'rgba(0,0,0,0)' : c.c, stroke: fadeCars > 0 ? c.c : '#0B1424', lw: 4, alpha: a });
    ctx.restore();
    if (fadeCars < 1) {
      A.rect(x - 85, c.y - 42, 170, 84, { r: 22, fill: c.c, alpha: roadIn * (1 - fadeCars) });
      A.rect(x + 20, c.y - 32, 38, 64, { r: 8, fill: '#0B1424', alpha: roadIn * (1 - fadeCars) * 0.8 });
      A.rect(x - 70, c.y - 30, 26, 60, { r: 6, fill: '#0B1424', alpha: roadIn * (1 - fadeCars) * 0.6 });
    }
    // teléfono
    const ps = A.pop(phoneT + i * 0.06, 0.45);
    if (ps > 0) {
      A.rings(x, c.y, phoneT + i * 0.06, { count: 3, speed: 120, gap: 0.35, maxR: 90, color: ACC, lw: 3, alpha: 0.8 });
      A.with(() => {
        A.lib.glowDot(ctx, x, c.y, 46, { color: ACC });
        A.rect(x - 18, c.y - 30, 36, 60, { r: 8, fill: '#111827', stroke: ACC, lw: 4 });
        A.rect(x - 12, c.y - 22, 24, 40, { r: 3, fill: ACC, alpha: 0.85 });
      }, { x: x, y: c.y, scale: ps });
    }
  });
}, { shake: shake });
A.flash(phoneT, 0.25, 0.25);

// --- Pin de Google Maps con ojo ---
if (pinP > 0) {
  const ps = A.pop(kG, 0.5);
  A.with(() => {
    ctx.save();
    ctx.beginPath();
    ctx.arc(540, pinY - 30, 62, Math.PI * 0.82, Math.PI * 2.18);
    ctx.lineTo(540, pinY + 50); ctx.closePath();
    ctx.fillStyle = '#EA4335'; ctx.fill();
    ctx.lineWidth = 5; ctx.strokeStyle = '#FFFFFF'; ctx.stroke();
    // ojo
    ctx.beginPath(); ctx.ellipse(540, pinY - 30, 38, 22, 0, 0, Math.PI * 2); ctx.fillStyle = '#FFFFFF'; ctx.fill();
    const look = Math.sin(t * 3) * 10;
    const blink = (t > kNo && t < kNo + 0.15) ? 0.2 : 1;
    ctx.beginPath(); ctx.ellipse(540 + look, pinY - 30, 13, 13 * blink, 0, 0, Math.PI * 2); ctx.fillStyle = '#0B1424'; ctx.fill();
    ctx.restore();
  }, { x: 540, y: pinY, scale: ps, alpha: pinP });
}

// --- Etiqueta inferior: AUTOS tachado → TELÉFONOS ---
const autosIn = A.p(kNo - 0.1, 0.4, 'softLand');
const swap = A.p(kVe, 0.35, 'softInOut');
if (autosIn > 0 && swap < 1) {
  const a = autosIn * (1 - swap);
  A.text('AUTOS', 540, 1500 + (1 - autosIn) * 30, { size: 130, color: '#FFFFFF', weight: 900, align: 'center', alpha: a });
  const st = A.p(kAut, 0.35, 'whip');
  if (st > 0) A.line([[300, 1480], [780, 1440]], { stroke: RED, lw: 16, progress: st, alpha: a });
}
if (swap > 0) {
  const s = A.pop(kTel - 0.2, 0.5);
  A.with(() => {
    A.text('TELÉFONOS', 540, 1500, { size: 130, color: ACC, weight: 900, align: 'center' });
  }, { x: 540, y: 1460, scale: Math.max(0.01, s), alpha: swap });
}

// pequeña chispa en "truco"
if (t > kTru && t < kTru + 0.6) A.rings(540, 840, kTru, { count: 1, speed: 900, maxR: 500, color: 'rgba(255,255,255,0.6)', lw: 3, alpha: 0.4 });
if (t > kRev && t < kG) A.text('?', 540, 600, { size: 140, color: ACC, weight: 900, align: 'center', alpha: A.p(kRev, 0.3) * (1 - A.p(kG - 0.2, 0.2)) });

const ac = A.accent;
A.bg('#0B1630', '#050A18');
const tU = A.k('ubicación', 1.0), tAct = A.k('activada,', 1.333), tEnv = A.k('envía', 2.333);
const tAn = A.k('anónima', 3.333), tDon = A.k('dónde', 3.667), tEst = A.k('estás', 4.0), tVel = A.k('velocidad', 5.333);

// ---------- PHONE ----------
const px = 360, py = 790, pw = 280, ph = 520;
const pin = A.p(0, 0.7, 'snapSettle');
const fl = Math.sin(t * 2) * 5;
const velP = A.p(tVel, 0.5, 'softLand');
A.with(() => {
  A.rect(px - pw/2 - 14, py - ph/2 - 14, pw + 28, ph + 28, { r: 44, fill: '#101C36', stroke: '#E8F4FF', lw: 6 });
  // screen
  ctx.save();
  ctx.beginPath(); ctx.rect(px - pw/2, py - ph/2, pw, ph); ctx.clip();
  ctx.fillStyle = '#0A1426'; ctx.fillRect(px - pw/2, py - ph/2, pw, ph);
  const scroll = 40 * Math.max(0, t - tDon) + 220 * Math.max(0, t - tVel) * velP;
  ctx.strokeStyle = '#1C3157'; ctx.lineWidth = 12;
  for (let i = -1; i < 8; i++) {
    const y = py - ph/2 + i * 90 + (scroll % 90);
    ctx.beginPath(); ctx.moveTo(px - pw/2, y); ctx.lineTo(px + pw/2, y); ctx.stroke();
  }
  [px - 90, px + 95].forEach(x => { ctx.beginPath(); ctx.moveTo(x, py - ph/2); ctx.lineTo(x, py + ph/2); ctx.stroke(); });
  ctx.strokeStyle = '#2B4A7E'; ctx.lineWidth = 26;
  ctx.beginPath(); ctx.moveTo(px, py - ph/2); ctx.lineTo(px, py + ph/2); ctx.stroke();
  // trail of past positions when moving
  if (t > tDon) {
    for (let j = 1; j < 6; j++) {
      const yy = py + 70 + j * 34 * (0.4 + velP);
      A.circle(px, yy, 7 - j, { fill: ac, alpha: 0.5 * (1 - j / 6) });
    }
  }
  ctx.restore();
  // top bar with toggle
  A.rect(px - pw/2, py - ph/2, pw, 90, { fill: '#13244A' });
  A.text('Ubicación', px - 40, py - ph/2 + 56, { size: 28, color: '#E8F4FF', weight: '700', align: 'center' });
  const tg = A.p(tAct, 0.35, 'snapSettle');
  const tx = px + 70, ty = py - ph/2 + 45;
  ctx.fillStyle = tg > 0.5 ? ac : '#3A4A66';
  ctx.beginPath(); ctx.arc(tx - 22, ty, 22, Math.PI/2, Math.PI*1.5); ctx.arc(tx + 22, ty, 22, -Math.PI/2, Math.PI/2); ctx.fill();
  A.circle(A.lerp(tx - 22, tx + 22, tg), ty, 17, { fill: '#FFFFFF' });
  // GPS dot
  const dy = py + 70;
  const ds = A.pop(tU, 0.45);
  if (ds > 0) {
    const on = A.p(tAct, 0.3);
    A.circle(px, dy, 34 * ds, { fill: ac, alpha: 0.18 + 0.1 * Math.sin(t * 6) });
    A.circle(px, dy, 17 * ds, { fill: on > 0.5 ? ac : '#8899AA', stroke: '#FFFFFF', lw: 5, glow: on > 0.5 ? 20 : 0 });
  }
}, { x: px, y: py, scale: A.lerp(0.6, 1, pin), alpha: pin, shake: t > tVel && t < tVel + 0.3 ? 4 : 0 });
if (t > tAct) A.rings(px, py + 70, tAct, { count: 3, speed: 260, gap: 0.35, maxR: 220, color: ac, lw: 4, alpha: 0.7 });

// ---------- SERVER ----------
const sx = 810, sy = 560;
const ss = A.pop(tEnv - 0.25, 0.5);
const packets = [];
let lastArrive = -10;
for (let i = 0; i < 12; i++) {
  const t0 = tEnv + i * 0.35, d = 0.8;
  if (t > t0 + d) lastArrive = t0 + d;
  if (t > t0 && t < t0 + d) packets.push((t - t0) / d);
}
if (ss > 0) {
  A.with(() => {
    for (let r = 0; r < 3; r++) {
      const y = sy + r * 64;
      A.rect(sx - 110, y, 220, 50, { r: 10, fill: '#13244A', stroke: '#E8F4FF', lw: 4 });
      const blink = (t - lastArrive) < 0.15 && r === Math.floor(lastArrive * 7) % 3;
      A.circle(sx + 80, y + 25, 8, { fill: blink ? '#FFFFFF' : ac, glow: blink ? 25 : 8 });
      A.rect(sx - 90, y + 20, 110, 10, { r: 5, fill: '#2B4A7E' });
    }
    A.text('GOOGLE', sx, sy + 245, { size: 38, color: '#E8F4FF', weight: '800', align: 'center' });
  }, { x: sx, y: sy + 90, scale: ss, alpha: A.clamp(ss) });
}
// arc path
const P0 = [px + 90, py - ph/2 - 20], P1 = [640, 400], P2 = [sx - 120, sy + 90];
const bz = (u) => [ (1-u)*(1-u)*P0[0] + 2*(1-u)*u*P1[0] + u*u*P2[0], (1-u)*(1-u)*P0[1] + 2*(1-u)*u*P1[1] + u*u*P2[1] ];
if (t > tEnv) {
  const lp = A.p(tEnv, 0.5, 'glide');
  const pts = []; for (let i = 0; i <= 20; i++) pts.push(bz(i / 20));
  A.line(pts, { stroke: ac, lw: 3, alpha: 0.45, dash: [10, 12], progress: lp });
  packets.forEach(u => {
    const e = u < 0.5 ? 2*u*u : 1 - Math.pow(-2*u + 2, 2) / 2;
    const [x, y] = bz(e);
    A.rect(x - 22, y - 15, 44, 30, { r: 7, fill: ac, glow: 18, alpha: 1 - Math.max(0, (u - 0.85) / 0.15) });
  });
  if (t < tEnv + 0.7) A.label('ENVÍA', 640, 450, { size: 40, bg: ac, color: '#06101F', scale: A.pop(tEnv, 0.4) });
}

// ---------- DATA CARD (secondary zone) ----------
const cp = A.p(tEnv + 0.3, 0.6, 'softLand');
if (cp > 0) {
  const cy = A.lerp(1420, 1350, cp);
  A.with(() => {
    A.rect(120, cy, 840, 380, { r: 28, fill: '#0E1A33', stroke: ac, lw: 4 });
    A.lib.hatch(ctx, [[120, cy], [960, cy], [960, cy + 380], [120, cy + 380]], { angle: 0.8, spacing: 26, width: 1, color: 'rgba(77,208,225,0.07)' });
    const rows = [cy + 85, cy + 200, cy + 315];
    const lab = (s, y) => A.text(s, 160, y + 12, { size: 30, color: '#8FA6C8', weight: '700', align: 'left' });
    // row 1 anonymous
    lab('USUARIO', rows[0]);
    const an = A.p(tAn, 0.35, 'whip');
    A.text('Juan Pérez', 440, rows[0] + 14, { size: 44, color: '#E8F4FF', weight: '700', align: 'left', alpha: 1 - A.p(tAn + 0.35, 0.2) });
    if (an > 0) {
      A.rect(430, rows[0] - 30, 250 * an, 56, { r: 8, fill: '#000000' });
      const as = A.pop(tAn + 0.3, 0.45);
      if (as > 0) A.label('ANÓNIMO', 770, rows[0] - 2, { size: 40, bg: ac, color: '#06101F', scale: as });
    }
    // row 2 position
    lab('POSICIÓN', rows[1]);
    if (t > tDon) {
      const s = '-33.44, -70.65';
      const n = Math.floor(A.p(tDon, 0.6, 'cruise') * s.length);
      A.text(s.slice(0, n), 440, rows[1] + 14, { size: 46, color: '#FFFFFF', weight: '800', align: 'left' });
      const pp = A.pop(tEst, 0.45);
      if (pp > 0) {
        A.circle(890, rows[1] - 8, 22 * pp, { fill: ac, stroke: '#FFFFFF', lw: 4, glow: 15 });
        A.circle(890, rows[1] - 8, 8 * pp, { fill: '#06101F' });
        if (t > tEst) A.rings(890, rows[1] - 8, tEst, { count: 2, speed: 120, gap: 0.5, maxR: 60, color: ac, lw: 3 });
      }
    }
    // row 3 speed
    lab('VELOCIDAD', rows[2]);
    if (t > tVel - 0.1) {
      const vp = A.p(tVel, 0.7, 'softLand');
      A.with(() => {
        A.text(A.counter(0, 38, vp, 0) + ' km/h', 440, rows[2] + 16, { size: 52, color: ac, weight: '900', align: 'left' });
